import marimo

app=marimo.App(width="medium")

@app.cell
def _():
    import marimo as mo
    from pathlib import Path
    import hashlib, io, json, math
    import numpy as np
    import pandas as pd
    import torch
    import torch.nn.functional as F
    from PIL import Image
    return mo, Path, hashlib, io, json, math, np, pd, torch, F, Image

@app.cell
def _(mo):
    mo.md("## Export observed-image blur proxies\nUse the same authorized ImageNet originals from the completed severity run. This exports 300 observations for the frozen 100 sources, with zero model calls. The rule will be applied using the separately frozen DIV2K threshold.")
    path_form=mo.ui.text(value='/marimo/data/imagenet_severity100_originals',label='ImageNet originals folder').form(submit_button_label='Apply path')
    start=mo.ui.run_button(label='Export ImageNet proxy CSV')
    mo.vstack([path_form,start])
    return path_form,start

